using Microsoft.Win32;using System.Drawing;using System.Drawing.Imaging;using System.Runtime.InteropServices;using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Interop;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Windows.Shapes;using Forms=System.Windows.Forms;using Point=System.Windows.Point;using Rectangle=System.Windows.Shapes.Rectangle;
namespace ChichiCapture;
public partial class MainWindow:Window{
 enum Tool{Select,Crop,Pen,Arrow,Rectangle,Ellipse,Text,Mosaic} Tool tool;Point start;Shape? preview;Polyline? stroke;BitmapSource? source;readonly AppSettings settings=AppSettings.Load();readonly Forms.NotifyIcon tray;HwndSource? hookSource;bool exiting;const int HK=1,WM_HOTKEY=0x0312,ALT=1,CTRL=2,SHIFT=4;
